        Map<String, BigDecimal> dueByGrade() {
            Map<String, BigDecimal> out = new LinkedHashMap<>();
            people.values().stream().filter(f -> !f.retired()).forEach(f -> out.merge(f.grade(),
                    f.dueTotal() == null ? zero() : f.dueTotal(), BigDecimal::add));
            return out;
        }

