        List<Member> members() {
            return people.values().stream().map(f -> {
                List<String> names = new ArrayList<>(List.of(f.name()));
                names.addAll(f.aliases());
                return new Member(names, f.dueTotal(), f.overdueTotal());
            }).toList();
        }
